head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > noSelect]<br/>copyType='default' 일때 마우스 드래그에 의한 Cell 텍스트 선택을 차단할지 설정합니다.",
    "validation" : [
        "copyType='default' 일때 마우스 드래그에 의한 Cell 텍스트 선택을 차단할지 설정합니다. copyType='native' 이면 noSelect 는 항상 false 로 동작합니다.",
        "true 설정 시 마우스 드래그에 의한 Cell 텍스트 선택을 차단합니다. GridView 최상위 요소에 'w2noselect' CSS 클래스가 추가되어 텍스트 드래그 선택이 웹브라우저 레벨에서 차단됩니다.",
        "false(기본값) 설정 시 마우스 드래그에 의한 Cell 텍스트 선택을 허용합니다.",
        "noSelect 는 마우스 드래그 텍스트 선택만 차단하며, Cell 선택이나 포커스 이동에는 영향이 없습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (Target 재생성 버튼 클릭 시 재실행)
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정 (con_ 옵션을 properties 객체로 모아 createCList 로 속성 문자열 생성, 빈값 자동 제외)
    //  - noSelect 는 boolean 이므로 gdl_boolean(value=1/2/3 · label=""/true/false) + getText() 로 값 취득 (미설정/true/false)
    //  - copyType 는 비boolean 정적 select(default/native) + getValue()
    let conNoSelect = con_noSelect.getText();
    let conCopyType = con_copyType.getValue();

    let properties = {
        copyType : conCopyType
    };
    // 미설정("") 일 때는 noSelect 속성 자체를 제외
    if (conNoSelect !== "") {
        properties.noSelect = conNoSelect;
    }
    let cList = $c.gcm.createCList(properties);

    // 이벤트 바인딩 없음 (oncellclick 제거)
    let eList = '';

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    let lblNoSelect = (conNoSelect === '') ? '미설정' : conNoSelect;
    $c.gcm.createLabel('label="noSelect=' + lblNoSelect + ' / copyType=' + conCopyType + ' 로 GridView 생성. Cell 의 텍스트를 마우스로 드래그하여 선택 차단/허용 여부를 확인하고, Cell 을 클릭하면 포커스/선택이 정상 이동함을 확인"', '', 'label1');

    // dataList 생성 (column id 를 col1~col4 로 맞춤, 드래그 선택 확인용 텍스트 채움)
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON([
        { col1 : "DragText0_0", col2 : "DragText0_1", col3 : "DragText0_2", col4 : "DragText0_3" },
        { col1 : "DragText1_0", col2 : "DragText1_1", col3 : "DragText1_2", col4 : "DragText1_3" },
        { col1 : "DragText2_0", col2 : "DragText2_1", col3 : "DragText2_2", col4 : "DragText2_3" },
        { col1 : "DragText3_0", col2 : "DragText3_1", col3 : "DragText3_2", col4 : "DragText3_3" }
    ]);

    // target 생성
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' ' + eList + ' dataList="data:dlt_bind" checkAllType="false" id="" style="width:480px;height:240px;">';
    strTarget += '<w2:caption style="" id="caption1" value="noSelect 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column1" value="name1"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column2" value="name2"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column3" value="name3"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column4" value="name4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col1"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col2"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col3"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // 그리드 생성 직후 현재 noSelect / copyType 옵션값을 자동 출력
    scwin.showNoSelectState();

    // GridView 최상위 요소에 mouseup 리스너 1회 등록 (Target 재생성 시 중복등록 방지 : 이전 핸들러 제거 후 재등록)
    scwin.bindDragSelectListener();
}



// GridView 영역에서 마우스 드래그로 텍스트를 선택(또는 차단)한 직후 현재 선택 텍스트를 자동 출력
//  - createEList 가 아닌 addEventListener 로 등록 (사용자 마우스업 시점에 window.getSelection() 읽기)
//  - comp_init / Target 재생성 시 중복 등록 방지 : scwin._dragSelectHandler 보관 후 재생성 시 먼저 제거
scwin.bindDragSelectListener = function () {
    // 페이지 scope 적용으로 컴포넌트 최상위 요소는 target1.render
    let root = target1.render;
    if (!root) {
        return;
    }

    // 이전 핸들러가 있으면 먼저 제거 (Target 재생성 시 중복 등록 방지)
    if (scwin._dragSelectHandler && scwin._dragSelectRoot) {
        scwin._dragSelectRoot.removeEventListener("mouseup", scwin._dragSelectHandler);
    }

    scwin._dragSelectHandler = function () {
        // 마우스업 시점의 선택 텍스트 취득 (noSelect=true 면 브라우저가 선택을 차단하여 빈 문자열)
        let selText = window.getSelection().toString();
        wf_body_bottom.getObj("scwin").setReturnValue('드래그 선택 텍스트: ' + selText);
    };

    scwin._dragSelectRoot = root;
    root.addEventListener("mouseup", scwin._dragSelectHandler);
}



// Target 재생성 시 현재 noSelect / copyType 옵션값을 자동 출력
scwin.showNoSelectState = function () {
    // 재생성 시 이전 출력 누적 방지 위해 리턴 값 초기화
    wf_body_bottom.getObj("scwin").btn_clear_onclick();

    let conNoSelect = con_noSelect.getText();
    let lblNoSelect = (conNoSelect === '') ? '미설정' : conNoSelect;

    wf_body_bottom.getObj("scwin").setReturnValue("[noSelect] " + lblNoSelect + " / [copyType] " + con_copyType.getValue());
}
